// effortTime formats seconds as m:ss or h:mm:ss.
func effortTime(sec float64) string {
	s := int(math.Round(sec))
	if s >= 3600 {
		return fmt.Sprintf("%d:%02d:%02d", s/3600, s/60%60, s%60)
	}
	return fmt.Sprintf("%d:%02d", s/60, s%60)
}

// effortName describes what an effort measures.
func effortName(kind string, key int) string {
	switch kind {
	case store.EffortDistance:
		return analysis.DistanceLabel(key)
	case store.EffortPower:
		return analysis.DurationLabel(key)
	case store.EffortClimb:
		return "Größter Anstieg"
	}
	return kind
}

// effortValue formats the value of an effort with its unit and, for
// distances, the speed or pace.
func effortValue(e store.Effort) (value, detail string) {
	switch e.Kind {
	case store.EffortDistance:
		mps := float64(e.Key) / e.Value
		if e.Group == analysis.GroupRun {
			return effortTime(e.Value), pace(mps) + " /km"
		}
		return effortTime(e.Value), kmh(mps) + " km/h"
	case store.EffortPower:
		return fmt.Sprintf("%.0f W", e.Value), ""
	case store.EffortClimb:
		d := ""
		if e.Extra > 0 {
			d = fmt.Sprintf("%s km · ⌀ %s %%", km(e.Extra), germanFloat(e.Value/e.Extra*100, 1))
		}
		return fmt.Sprintf("%.0f Hm", e.Value), d
	}
	return strconv.FormatFloat(e.Value, 'f', -1, 64), ""
}

// effortView is one best effort of an activity on the detail page.
type effortView struct {
	Name, Value, Detail string
	StartS, EndS        float64
	// Medal is set for the top three overall or within the year.
	Medal string
	Rank  string
}

func medal(rank int) string {
	return map[int]string{1: "🥇", 2: "🥈", 3: "🥉"}[rank]
}

func effortViews(list []store.RankedEffort, year int) (top, all []effortView) {
	for _, e := range list {
		v := effortView{Name: effortName(e.Kind, e.Key), StartS: e.StartS, EndS: e.EndS}
		v.Value, v.Detail = effortValue(e.Effort)
		switch {
		case e.RankAll <= 3:
			v.Medal, v.Rank = medal(e.RankAll), fmt.Sprintf("%d. gesamt", e.RankAll)
		case e.RankYear <= 3:
			v.Medal, v.Rank = medal(e.RankYear), fmt.Sprintf("%d. in %d", e.RankYear, year)
		default:
			v.Rank = fmt.Sprintf("%d. in %d · %d. gesamt", e.RankYear, year, e.RankAll)
		}
		all = append(all, v)
		if v.Medal != "" {
			top = append(top, v)
		}
	}
	return top, all
}

// lapView is a row of the lap table.
type lapView struct {
	N            int
	Distance     string
	Time         string
	Speed        string
	HR, Power    string
	Ascent       string
	StartS, EndS float64
}

func lapViews(laps []store.Lap, run bool) (rows []lapView, auto bool) {
	for i, l := range laps {
		v := lapView{N: i + 1, Distance: km(l.DistanceM), Time: effortTime(l.TimerS), StartS: l.StartS, EndS: l.EndS,
			HR: orDash(l.AvgHR), Power: orDash(l.AvgPower), Ascent: orDash(l.AscentM)}
		speed := l.AvgSpeed
		if speed == 0 && l.TimerS > 0 {
			speed = l.DistanceM / l.TimerS
		}
		if run {
			v.Speed = pace(speed)
		} else {
			v.Speed = kmh(speed)
		}
		rows = append(rows, v)
		auto = auto || l.Auto
	}
	return rows, auto
}

// weatherView is the weather line of the detail page.
type weatherView struct {
	Icon, Label, Temp, Wind, Precip string
}

// wmo maps WMO weather codes (as used by Open-Meteo) to icon and label.
func wmo(code int) (string, string) {
	switch {
	case code == 0:
		return "☀️", "Klar"
	case code <= 2:
		return "🌤️", "Leicht bewölkt"
	case code == 3:
		return "☁️", "Bewölkt"
	case code == 45 || code == 48:
		return "🌫️", "Nebel"
	case code >= 51 && code <= 57:
		return "🌦️", "Nieselregen"
	case code >= 61 && code <= 67:
		return "🌧️", "Regen"
	case code >= 71 && code <= 77:
		return "🌨️", "Schnee"
	case code >= 80 && code <= 82:
		return "🌦️", "Regenschauer"
	case code == 85 || code == 86:
		return "🌨️", "Schneeschauer"
	case code >= 95:
		return "⛈️", "Gewitter"
	}
	return "🌡️", "Wetter"
}

var compass = [...]string{"N", "NO", "O", "SO", "S", "SW", "W", "NW"}

func newWeatherView(w store.Weather) weatherView {
	v := weatherView{}
	v.Icon, v.Label = wmo(w.Code)
	// Compare the formatted values: math.Round and %.0f round halves differently.
	lo, hi, felt := fmt.Sprintf("%.0f", w.TempMinC), fmt.Sprintf("%.0f", w.TempMaxC), fmt.Sprintf("%.0f", w.ApparentC)
	if lo == hi {
		v.Temp = hi + " °C"
	} else {
		v.Temp = lo + "–" + hi + " °C"
	}
	if felt != lo {
		v.Temp += " (gefühlt " + felt + " °C)"
	}
	dir := compass[int(math.Round(w.WindDirDeg/45))%8]
	v.Wind = fmt.Sprintf("%.0f km/h aus %s", w.WindKmh, dir)
	if w.GustKmh >= w.WindKmh+10 {
		v.Wind += fmt.Sprintf(", Böen %.0f km/h", w.GustKmh)
	}
	if w.PrecipMM >= 0.1 {
		v.Precip = germanFloat(w.PrecipMM, 1) + " mm Niederschlag"
	}
	return v
}

// trainingView lists the training values of an activity that were recorded.
type trainingView struct {
	Label, Value string
}

func trainingViews(t store.Training) []trainingView {
	var out []trainingView
	add := func(label, value string) { out = append(out, trainingView{label, value}) }
	if t.Effect > 0 || t.AnaerobicEffect > 0 {
		add("Trainingseffekt", fmt.Sprintf("%s aerob · %s anaerob", germanFloat(t.Effect, 1), germanFloat(t.AnaerobicEffect, 1)))
	}
	if t.Load > 0 {
		add("Trainingsbelastung", fmt.Sprintf("%.0f", t.Load))
	}
	if t.NormalizedPower > 0 {
		add("Normalized Power", fmt.Sprintf("%d W", t.NormalizedPower))
	}
	if t.TSS > 0 {
		add("TSS · IF", fmt.Sprintf("%.0f · %s", t.TSS, germanFloat(t.IntensityFactor, 2)))
	}
	if t.RPE > 0 {
		add("Anstrengung (RPE)", germanFloat(t.RPE, 0)+" / 10")
	}
	return out
}

// ownLoadViews lists my Velo's own load values.
func ownLoadViews(o store.OwnLoad) []trainingView {
	var out []trainingView
	if o.TRIMP > 0 {
		out = append(out, trainingView{"TRIMP", fmt.Sprintf("%.0f", o.TRIMP)})
	}
	if o.TSS > 0 {
		out = append(out, trainingView{"TSS (eigene)", fmt.Sprintf("%.0f · NP %d W", o.TSS, o.NP)})
	}
	return out
}

// zoneRow is one bar of the time-in-zones chart of an activity.
type zoneRow struct {
	Zone  int
	Range string
	Time  string
	Pct   float64
}

// zoneSet is the zone chart of one kind (heart rate or power).
type zoneSet struct {
	Kind  string
	Title string
	Rows  []zoneRow
}

// zoneSets turns the stored zones into bar charts. Zone 0 (below zone 1)
// is left out; shares are relative to the time in zones 1+.
func zoneSets(zones []store.ZoneSeconds) []zoneSet {
	var out []zoneSet
	for _, kind := range []string{store.ZoneHR, store.ZonePower} {
		var rows []zoneRow
		total := 0.0
		for _, z := range zones {
			if z.Kind == kind && z.Zone > 0 {
				total += z.Seconds
			}
		}
		if total == 0 {
			continue
		}
		unit := map[string]string{store.ZoneHR: "bpm", store.ZonePower: "W"}[kind]
		for _, z := range zones {
			if z.Kind != kind || z.Zone == 0 {
				continue
			}
			r := fmt.Sprintf("%.0f–%.0f %s", z.Low, z.High, unit)
			if kind == store.ZonePower && z.High >= 4000 {
				r = fmt.Sprintf("ab %.0f W", z.Low)
			}
			rows = append(rows, zoneRow{Zone: z.Zone, Range: r, Time: effortTime(z.Seconds), Pct: math.Round(1000*z.Seconds/total) / 10})
		}
		out = append(out, zoneSet{Kind: kind, Title: map[string]string{store.ZoneHR: "Herzfrequenz-Zonen", store.ZonePower: "Leistungszonen"}[kind], Rows: rows})
	}
	return out
}

// thresholdNote describes which thresholds the zones of an activity use.
// FTP is only mentioned with power zones: watches report a (default) FTP
// even for rides without power meter.
func thresholdNote(t store.Thresholds, zones []zoneSet) string {
	hasPower := false
	for _, z := range zones {
		hasPower = hasPower || z.Kind == store.ZonePower
	}
	var parts []string
	if t.MaxHR > 0 {
		parts = append(parts, fmt.Sprintf("max. HF %d", t.MaxHR))
	}
	if t.RestHR > 0 {
		parts = append(parts, fmt.Sprintf("Ruhepuls %d", t.RestHR))
	}
	if t.FTP > 0 && hasPower {
		parts = append(parts, fmt.Sprintf("FTP %d W", t.FTP))
	}
	if len(parts) == 0 {
		return ""
	}
	src := "von der Uhr"
	if t.Source == store.ThresholdsManual {
		src = "manuell"
	}
	return "Schwellen " + src + ": " + strings.Join(parts, " · ")
}
